public class Main {
    static int remaining(int total, int borrowed) {
        return total - borrowed;
    }

    public static void main(String[] args) {
        int available = remaining(7, 2);
        System.out.println(available);
    }
}

import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        ArrayList<String> titles = new ArrayList<>();
        titles.add("Java Basics");
        titles.add("Clean Code");
        System.out.println(titles.size());
        for (String title : titles) {
            System.out.println(title);
        }
    }
}

public class Main {
    record Book(String id, String title, String borrower) {}

    public static void main(String[] args) {
        Book before = new Book("B001", "Java Basics", "");
        Book after = new Book(before.id(), before.title(), "Mona");
        System.out.println(before.borrower().isEmpty());
        System.out.println(after.id() + " " + after.borrower());
    }
}
